// Bundles the OS's own assistant code (docs/core.js) with the server shims into the two Edge Functions.
// Run: node build.mjs   (uses esbuild; npm: imports stay external for Deno to resolve)
import { build } from "esbuild";

const banner = `// @ts-nocheck
// GENERATED by build.mjs from docs/core.js + server/*. Edit those files, then run: node build.mjs
var location = { hash: "" };`;

for (const name of ["telegram", "assistant"]) {
  await build({
    entryPoints: [`server/${name}.ts`],
    outfile: `supabase/functions/${name}/index.ts`,
    bundle: true, format: "esm", platform: "neutral", target: "es2022",
    external: ["npm:*", "jsr:*"], banner: { js: banner }, legalComments: "none", charset: "utf8",
  });
  console.log("built", name);
}
